def _proper_divisor_sum(number):
    """Return the sum of the proper divisors of ``number``."""
    if number <= 1:
        return 0
    total = 1
    for divisor in range(2, isqrt(number) + 1):
        if number % divisor == 0:
            total += divisor
            paired_divisor = number // divisor
            if paired_divisor != divisor:
                total += paired_divisor
    return total


def amicable_numbers_sum(limit):
    """Write a function to sum all amicable numbers from 1 to a specified number."""
    if limit < 1:
        return 0

    proper_divisor_sums = [0] * (limit + 1)
    for divisor in range(1, limit // 2 + 1):
        for multiple in range(divisor * 2, limit + 1, divisor):
            proper_divisor_sums[multiple] += divisor

    total = 0
    for number in range(1, limit + 1):
